    valid_date('15-01-2012') => False

    valid_date('04-0-2040') => False

    valid_date('06-04-2020') => True

    valid_date('06/04/2020') => False
    """

    # split date string to year, month and day values as integers
    month, day, year = map(int, date.split('-'))

    # check if the date string is not empty
    if date and len(date) == 10:
        # check if month is between 1 and 12 inclusive
        if 1 <= month <= 12:
            # check the number of days based on the month
            if month in [1, 3, 5, 7, 8, 10, 12]:
                if 1 <= day <= 31:
                    return True
            elif month in [4, 6, 9, 11]:
                if 1 <= day <= 30:
                    return True
            elif month == 2:
                if 1 <= day <= 29:
                    # check for leap year
                    if year % 4 == 0:
                        if year % 100 == 0:
                            if year % 400 == 0:
                                return True
                            else:
                                return False
                        else:
                            return True
                    else:
                        return False
        else:
            return False
    else:
